import type { User } from '@/types/api';
import { Spinner } from '@/components/ui/spinner';
import { Table } from '@/components/ui/table';
import { useQueryClient } from '@tanstack/react-query';
import { formatDate } from '@/utils/format';

import { useUsers, getUsersQueryOptions } from '../api/get-users';
import { useUpdateUserRole } from '../api/update-user-role';

import { DeleteUser } from './delete-user';

const ROLES = ['ADMIN', 'USER'] as const;

export const UsersList = () => {
  const usersQuery = useUsers();
  const queryClient = useQueryClient();

  const updateUserRoleMutation = useUpdateUserRole();

  if (usersQuery.isLoading) {
    return (
      <div className="flex h-48 w-full items-center justify-center">
        <Spinner size="lg" />
      </div>
    );
  }

  const users = usersQuery.data?.data;

  if (!users) return null;

  const handleRoleChange = (userId: string, newRole: 'ADMIN' | 'USER') => {
    // Optimistic update of the table data to show the new role immediately
    queryClient.setQueryData<any>(getUsersQueryOptions().queryKey, (old) => {
      if (!old) return old;
      return {
        ...old,
        data: old.data.map((u: any) =>
          u.id === userId ? { ...u, role: newRole } : u
        ),
      };
    });
    updateUserRoleMutation.mutate({ userId, newRole });
  };

  return (
    <Table
      data={users}
      columns={[
        {
          title: 'First Name',
          field: 'firstName',
        },
        {
          title: 'Last Name',
          field: 'lastName',
        },
        {
          title: 'Email',
          field: 'email',
        },
        {
          title: 'Role',
          field: 'role',
          Cell({ entry }) {
            return (
              <select
                value={entry.role}
                onChange={(e) =>
                  handleRoleChange(entry.id, e.target.value as 'ADMIN' | 'USER')
                }
                disabled={updateUserRoleMutation.isPending}
                className="block w-full rounded-md border-gray-600 py-1 pl-2 pr-8 text-sm focus:border-blue-500 focus:outline-none focus:ring-blue-500 disabled:opacity-50 disabled:pointer-events-none"
              >
                {ROLES.map((role) => (
                  <option key={role} value={role}>
                    {role}
                  </option>
                ))}
              </select>
            );
          },
        },
        {
          title: 'Created At',
          field: 'createdAt',
          Cell({ entry: { createdAt } }) {
            return <span>{formatDate(createdAt)}</span>;
          },
        },
        {
          title: '',
          field: 'id',
          Cell({ entry: { id } }) {
            return <DeleteUser id={id} />;
          },
        },
      ]}
    />
  );
};

