import { useMutation, useQueryClient } from '@tanstack/react-query';
import { z } from 'zod';

import { api } from '@/lib/api-client';
import { useNotifications } from '@/components/ui/notifications';
import { MutationConfig } from '@/lib/react-query';
import { User } from '@/types/api';

import { getUsersQueryOptions } from './get-users';

export const updateUserRoleSchema = z.object({
  userId: z.string(),
  newRole: z.enum(['ADMIN', 'USER']),
});

export type UpdateUserRoleInput = z.infer<typeof updateUserRoleSchema>;

export const updateUserRole = async ({ userId, newRole }: UpdateUserRoleInput) => {
  return api.patch<User>(`/users/${userId}/role`, { role: newRole });
};

type UseUpdateUserRoleOptions = {
  mutationConfig?: MutationConfig<typeof updateUserRole>;
};

export const useUpdateUserRole = ({
  mutationConfig,
}: UseUpdateUserRoleOptions = {}) => {
  const queryClient = useQueryClient();
  const { addNotification } = useNotifications();

  const { onSuccess, ...restConfig } = mutationConfig || {};

  return useMutation({
    onSuccess: (...args) => {
      addNotification({
        type: 'success',
        title: 'Role Updated',
      });
      queryClient.invalidateQueries({ queryKey: getUsersQueryOptions().queryKey });
      onSuccess?.(...args);
    },
    ...restConfig,
    mutationFn: updateUserRole,
  });
};
